parameters.jsCode:
const body = $json.body || {};
const faq = [{"q":"What kind of projects do you build?","a":"Full-stack web apps, Web3/blockchain systems, and AI-powered automation with n8n — real, deployed, and verifiable, not mockups or pitch decks."},{"q":"How much do the automation templates cost?","a":"Templates range from $149 to $199 depending on complexity — each is a tested, working n8n workflow with setup docs. See the Automations page for the current list."},{"q":"Do you use AI to build the projects?","a":"Yes, openly. AI accelerates implementation, but every architecture decision, code review, and what actually ships is directed personally — explained on the homepage as the 70/30 Engineering Rule."},{"q":"Can I get something custom built, not from the template list?","a":"Yes — reach out through the contact form with what you need and a fixed-price proposal gets scoped from there."},{"q":"Are you currently available for new projects?","a":"Check the availability badge on the homepage for real-time status, or just ask directly — usually the fastest way to get a clear answer."},{"q":"Do you work with clients outside Pakistan?","a":"Yes — delivery is remote and async, so location isn't a blocker."},{"q":"What happens after I buy a template?","a":"You get the full workflow JSON plus a setup guide by email, ready to import into your own n8n instance and connect your own accounts."}];
const faqText = faq.map((item, i) => `${i + 1}. Q: ${item.q}\nA: ${item.a}`).join('\n\n');
return {
  json: {
    name: body.name || 'there',
    email: body.email || '',
    message: body.message || '',
    faqText,
  },
};

