const raw = $json.candidates[0].content.parts[0].text;
const parsed = JSON.parse(raw);
const lead = $('Load FAQ + Context').item.json;
return {
  json: {
    name: lead.name,
    email: lead.email,
    message: lead.message,
    answerable: parsed.answerable === true,
    customerReply: parsed.customerReply || '',
    escalationSummary: parsed.escalationSummary || '',
  },
};
